contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint amount, bool badData) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000);
        require(address(this).balance >= amount);

        uint depositsBefore = c.depositsCount(); if (__ESBMC_reverted()) return;

        bytes memory data;
        if (badData) {
            data = hex"deadbeef";
        } else {
            data = bytes("");
        }

        bool reverted;
        c.sendMoney(address(this), amount, data); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        uint depositsAfter = c.depositsCount(); if (__ESBMC_reverted()) return;

        assert(depositsAfter == depositsBefore);
    }

    receive() external payable {}
}

